{
  "findings": [
    {
      "ref": "[D175]",
      "area": "contact",
      "claim": "Strangers can enter any child's virtual home.",
      "stance": "risk",
      "quote": "Other players can request to friend kids, and kids can accept or decline a request. However, any other player, friend or not, can enter anyone's home."
    },
    {
      "ref": "[D175]",
      "area": "contact",
      "claim": "Chat is pre-set and can be turned off.",
      "stance": "mitigation",
      "quote": "The chat option is pre-set: Kids have to choose from certain words or phrases, or use emojis."
    },
    {
      "ref": "[D175]",
      "area": "money",
      "claim": "The app pushes in-app purchases to remove ads and buy coins.",
      "stance": "risk",
      "quote": "Ads appear occasionally throughout unless kids make an in-app purchase to get rid of them. Coins allow kids to furnish their home, dress their avatar, buy food, and so on. Kids earn coins by playing or watching video ads, or they can buy coins through in-app purchases."
    },
    {
      "ref": "[D175]",
      "area": "data",
      "claim": "The app collects user information and shares it as described in its privacy policy.",
      "stance": "risk",
      "quote": "Read the [developer's privacy policy](https://www.iubenda.com/privacy-policy/33593894) for details on how your (or your kids') information is collected, used, and shared and any choices you may have in the matter, and note that privacy policies and terms of service frequently change."
    },
    {
      "ref": "[D175]",
      "area": "age_gating",
      "claim": "The app requires users to choose a name that is not real or offensive, but does not enforce strict age verification.",
      "stance": "neutral",
      "quote": "When kids make their user profile they aren't allowed to use real names, or names that could be suggestive or offensive."
    },
    {
      "ref": "[D175]",
      "area": "content",
      "claim": "The app includes potty humor and a poop emoji that makes a fart sound.",
      "stance": "neutral",
      "quote": "There's some potty humor in the chat options, including a poop emoji that makes a fart sound."
    }
  ]
}
